 box(root,0xbfa57c,0,.21,.20,1.75,.46,.64);box(root,0xe9debd,0,.46,.20,1.86,.05,.76);for(const x of [-.55,0,.55])box(root,0xa18c68,x,.3,.53,.035,.055,.025);box(root,0xcdb082,-.42,.50,.19,.62,.035,.48);
 const teddy=createTeddy(root,options.actor||0),{avatar,arms,body}=teddy;avatar.position.set(-.22,.10,-.23);const hat=new T.Group();body.add(hat);hat.position.y=1.04;cyl(hat,0xfffae9,0,.045,0,.20,.19,.08);cyl(hat,0xfffae9,0,.14,0,.175,.19,.17);for(let i=0;i<5;i++){const a=i*1.256;ball(hat,0xf6f2e3,Math.cos(a)*.11,.22,Math.sin(a)*.08,.09)}
 const pan=new T.Group();root.add(pan);pan.position.set(.46,.49,.2);cyl(pan,0x4b6659,0,.02,0,.25,.24,.035);cyl(pan,0x687c69,0,.1,0,.235,.18,.17);cyl(pan,0xcaa76a,0,.183,0,.213,.213,.008);box(pan,0x8c7554,.31,.11,0,.24,.04,.055);
