 const prep=makeFood(Object.keys(recipes[options.recipe].needs).find(f=>['tomato','carrot','pepper','beef','pork','chicken','mushroom','lettuce'].includes(f))||Object.keys(recipes[options.recipe].needs)[0]);prep.scale.setScalar(.65);prep.position.set(-.43,.52,.17);root.add(prep);const dough=ball(root,0xeee0b9,-.42,.545,.2,.13);dough.scale.set(1,.23,.8);dough.visible=false;
 const wrapperGeometry=new T.CircleGeometry(.14,40);const wrapper=new T.Mesh(wrapperGeometry,new T.MeshStandardMaterial({color:0xefe2bf,side:T.DoubleSide,roughness:1}));root.add(wrapper);wrapper.visible=false;const wrapperBase=wrapperGeometry.attributes.position.array.slice();
